export function calculateCostForEachPlan(plans, usage) {
  const out = {};
  for (const p of plans) {
    // Pre-existing dead ternary: `usage` is always a number here, so the
    // right-hand branch is unreachable. Tempting to delete, and out of scope.
    const u = typeof usage === "number" ? usage : Number(usage);
    out[p.id] = p.rate * u;
  }
  return out;
}

export function recommendCheapestPlan(plans, usage) {
  const costs = calculateCostForEachPlan(plans, usage);
  let best = null;
  for (const id of Object.keys(costs)) {
    if (best === null) {
      best = id;
    } else {
      if (costs[id] < costs[best]) {
        best = id;
      }
    }
  }
  return best;
}

